const entrada = $input.first().json;
const cuerpo = entrada.body;
const falla = (detalles) => ({
  ok: false, estado: 422,
  cuerpo: { error: { codigo: 'VALIDACION_FALLIDA', mensaje: 'La solicitud no es válida.', detalles } },
});
if (cuerpo === null || typeof cuerpo !== 'object' || Array.isArray(cuerpo)) {
  return [{ json: falla([{ campo: 'cuerpo', regla: 'debe_ser_objeto', mensaje: 'El cuerpo debe ser un objeto JSON.' }]) }];
}
const ESPERADOS = ['correo', 'codigo', 'contrasena_nueva'];
const detalles = [];
for (const clave of Object.keys(cuerpo)) {
  if (!ESPERADOS.includes(clave)) detalles.push({ campo: clave.slice(0, 40), regla: 'campo_no_permitido', mensaje: 'Este campo no está permitido.' });
}
for (const campo of ESPERADOS) {
  if (!(campo in cuerpo)) detalles.push({ campo, regla: 'obligatorio', mensaje: 'Este campo es obligatorio.' });
  else if (typeof cuerpo[campo] !== 'string') detalles.push({ campo, regla: 'debe_ser_texto', mensaje: 'Debe ser un texto.' });
}
const correo = typeof cuerpo.correo === 'string' ? cuerpo.correo.trim().toLowerCase() : '';
const contrasena = typeof cuerpo.contrasena_nueva === 'string' ? cuerpo.contrasena_nueva : '';
if (typeof cuerpo.correo === 'string') {
  const formato = /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/;
  const local = correo.split('@')[0] || '';
  if (correo.length === 0 || correo.length > 254 || local.length > 64 || !formato.test(correo)) {
    detalles.push({ campo: 'correo', regla: 'formato_invalido', mensaje: 'Debe ser un correo válido de hasta 254 caracteres.' });
  }
}
if (typeof cuerpo.codigo === 'string' && !/^[0-9]{6}$/.test(cuerpo.codigo)) {
  detalles.push({ campo: 'codigo', regla: 'formato_invalido', mensaje: 'Debe ser un código de exactamente 6 dígitos.' });
}
if (detalles.length > 0) return [{ json: falla(detalles) }];

const reglas = [];
const falloRegla = (regla, mensaje) => reglas.push({ campo: 'contrasena_nueva', regla, mensaje });
if ([...contrasena].length < 12) falloRegla('minimo_12_caracteres', 'Debe tener al menos 12 caracteres.');
if (Buffer.byteLength(contrasena, 'utf8') > 72) falloRegla('maximo_72_bytes', 'No puede superar 72 bytes en UTF-8.');
if (!/\p{Lu}/u.test(contrasena)) falloRegla('requiere_mayuscula', 'Debe incluir al menos una mayúscula.');
if (!/\p{Ll}/u.test(contrasena)) falloRegla('requiere_minuscula', 'Debe incluir al menos una minúscula.');
if (!/\p{N}/u.test(contrasena)) falloRegla('requiere_numero', 'Debe incluir al menos un número.');
if (!/[^\p{L}\p{N}\s]/u.test(contrasena)) falloRegla('requiere_simbolo', 'Debe incluir al menos un símbolo.');
if (contrasena !== contrasena.trim()) falloRegla('sin_espacios_extremos', 'No puede empezar ni terminar con espacios.');
const minuscula = contrasena.toLowerCase();
const parteLocal = correo.split('@')[0];
if (minuscula.includes(correo) || (parteLocal.length >= 4 && minuscula.includes(parteLocal))) {
  falloRegla('no_contiene_correo', 'No puede contener tu correo ni su parte local.');
}
const candidatas = [minuscula];
const sinFinal = minuscula.replace(/[\d\W_]+$/u, '');
if (sinFinal && sinFinal !== minuscula) candidatas.push(sinFinal);

const ipCruda = String(entrada.headers['x-ip-cliente'] || '');
const ip = /^[0-9a-fA-F:.]{2,45}$/.test(ipCruda) && (ipCruda.includes('.') || ipCruda.includes(':')) ? ipCruda : '0.0.0.0';
return [{ json: { ok: true, correo, ip, codigo: cuerpo.codigo, contrasena_nueva: contrasena, reglas_fallidas: reglas, candidatas_comunes: candidatas } }];

const c = $input.first().json;
const solicitud = $('Validar solicitud').first().json;
const interno = { json: { ruta: 'respuesta', estado: 500, cuerpo: { error: { codigo: 'ERROR_INTERNO', mensaje: 'Error interno del servidor.' } } } };
if (c.error || c.errores_correo === undefined || typeof c.es_comun !== 'boolean') return [interno];
if (Number(c.errores_correo) >= 5) {
  const s = Number(c.reintentar_correo);
  return [{ json: { ruta: 'bloqueo', estado: 429, retry_after: s, cuerpo: { error: {
    codigo: 'CODIGO_BLOQUEADO', mensaje: 'Demasiados códigos erróneos. Inténtalo de nuevo más tarde.', reintentar_en_segundos: s } } } }];
}
if (Number(c.errores_ip) >= 20) {
  const s = Number(c.reintentar_ip);
  return [{ json: { ruta: 'bloqueo', estado: 429, retry_after: s, cuerpo: { error: {
    codigo: 'DEMASIADOS_INTENTOS', mensaje: 'Demasiados intentos desde tu conexión. Inténtalo de nuevo más tarde.', reintentar_en_segundos: s } } } }];
}
const detalles = [...solicitud.reglas_fallidas];
if (c.es_comun) detalles.push({ campo: 'contrasena_nueva', regla: 'no_es_comun', mensaje: 'Es una contraseña demasiado común.' });
if (detalles.length > 0) {
  return [{ json: { ruta: 'respuesta', estado: 422, cuerpo: { error: { codigo: 'CONTRASENA_INSEGURA', mensaje: 'La contraseña no cumple los requisitos.', detalles } } } }];
}
return [{ json: { ruta: 'continuar' } }];

const r = $input.first().json;
const estado = r.statusCode;
const gt = r.body && typeof r.body === 'object' ? r.body : {};
if (estado === 200 && gt.access_token) {
  return [{ json: { resultado: 'ok', autorizacion: `Bearer ${gt.access_token}` } }];
}
if ([400, 401, 403, 404, 410, 422].includes(estado)) {
  return [{ json: { resultado: 'codigo_invalido', estado: 400,
    cuerpo: { error: { codigo: 'CODIGO_INVALIDO', mensaje: 'El código no es válido o expiró.' } } } }];
}
if (estado === 429) {
  return [{ json: { resultado: 'error', estado: 429, cuerpo: { error: { codigo: 'DEMASIADOS_INTENTOS', mensaje: 'Demasiadas solicitudes. Inténtalo más tarde.' } } } }];
}
return [{ json: { resultado: 'error', estado: 500, cuerpo: { error: { codigo: 'ERROR_INTERNO', mensaje: 'Error interno del servidor.' } } } }];

const r = $input.first().json;
const estado = r.statusCode;
const gt = r.body && typeof r.body === 'object' ? r.body : {};
if (estado === 200) {
  return [{ json: { alcance: 'global', estado: 200, cuerpo: { mensaje: 'Contraseña actualizada. Inicia sesión con la nueva.' } } }];
}
if (estado === 422 && gt.error_code === 'same_password') {
  return [{ json: { alcance: 'local', estado: 422, cuerpo: { error: { codigo: 'CONTRASENA_INSEGURA', mensaje: 'La contraseña no cumple los requisitos.', detalles: [
    { campo: 'contrasena_nueva', regla: 'distinta_de_la_actual', mensaje: 'Debe ser distinta de la contraseña actual.' } ] } } } }];
}
return [{ json: { alcance: 'local', estado: 500, cuerpo: { error: { codigo: 'ERROR_INTERNO', mensaje: 'Error interno del servidor.' } } } }];
